-- Example provisioning rule demonstrating the Lua scripting bridge:
-- forces ACS connection-request credentials, derives the WiFi SSID from the WAN MAC
-- address, and manages a demo port-forwarding entry via addObject/deleteObject.
-- Uses the global safe(fn, ...) helper (acs/scripts/functions.go) instead of pcall at
-- every call site - it has the same semantics as Lua's pcall but also logs failures
-- automatically through the engine's [script:<serial>] log channel.
-- Runs on device boot/bootstrap. Adjust `events`/`requests` or delete this row via the
-- admin panel's Provisioning screen once you've validated it against a real/simulated CPE.
insert into provisions (name, events, requests, script)
values ('Multiplay WiFi + ACS credentials', '0 BOOTSTRAP,1 BOOT', '', '["-- Provision: force ACS connection-request credentials, derive the WiFi SSID from\\n-- the WAN MAC address, and manage a demo port-forwarding entry.\\n-- Runs on 0 BOOTSTRAP / 1 BOOT (see provisions.events); safe to re-run since every\\n-- mutation below is idempotent. Uses the global safe() helper (acs/scripts/functions.go)\\n-- instead of pcall, so bridge faults get logged automatically without repeating\\n-- pcall+log boilerplate at every call site.\\nlocal root = device.root\\n\\nlocal wanMacPath = root .. \\".WANDevice.1.WANConnectionDevice.1.WANIPConnection.1.MACAddress\\"\\nlocal mgmtUserPath = root .. \\".DeviceInfo.ManagementServer.ConnectionRequestUsername\\"\\nlocal mgmtPassPath = root .. \\".DeviceInfo.ManagementServer.ConnectionRequestPassword\\"\\nlocal ssidPath = root .. \\".LANDevice.1.WLANConfiguration.1.SSID\\"\\n\\n-- 1. Pull the LANDevice + ManagementServer branches, plus the WAN MAC leaf, in one round trip\\nlocal ok, params = safe(getParameterValues, root .. \\".LANDevice.\\", root .. \\".DeviceInfo.ManagementServer.\\", wanMacPath)\\nif not ok then\\n    return\\nend\\n\\n-- 2. Force the ACS connection-request credentials\\nsafe(setParameterValues, {\\n    [mgmtUserPath] = \\"ACS\\",\\n    [mgmtPassPath] = \\"ACS\\",\\n})\\n\\n-- 3. Rename the first SSID using the last 4 bytes of the WAN MAC address\\nlocal wanMac = params[wanMacPath]\\nif wanMac and wanMac ~= \\"\\" then\\n    local macHex = wanMac:gsub(\\":\\", \\"\\"):gsub(\\"-\\", \\"\\"):upper()\\n    if #macHex >= 8 then\\n        local ssid = \\"Multiplay_\\" .. macHex:sub(-8)\\n        if safe(setParameter, ssidPath, ssid, \\"RWS\\") then\\n            log(\\"SSID updated\\", ssid)\\n        end\\n    else\\n        log(\\"WAN MAC address too short to derive an SSID suffix\\", wanMac)\\n    end\\nelse\\n    log(\\"WAN MAC address not available\\", wanMacPath)\\nend\\n\\n-- 4. Ensure a demo port-forwarding rule exists on the WAN connection\\n--    (this also proves addObject/deleteObject round-trip correctly against the CPE)\\nlocal portMappingBase = root .. \\".WANDevice.1.WANConnectionDevice.1.WANIPConnection.1.PortMapping.\\"\\nlocal tag = \\"ACS-managed-rule\\"\\nlocal desired = {\\n    PortMappingDescription = tag,\\n    PortMappingEnabled = \\"1\\",\\n    PortMappingProtocol = \\"TCP\\",\\n    ExternalPort = \\"8080\\",\\n    InternalPort = \\"80\\",\\n    InternalClient = \\"192.168.1.100\\",\\n    PortMappingLeaseDuration = \\"0\\",\\n}\\n\\nlocal pmOk, pmValues = safe(getParameterValues, portMappingBase)\\nif pmOk then\\n    local existingPath = nil\\n    for path, value in pairs(pmValues) do\\n        if path:match(\\"%.PortMappingDescription$\\") and value == tag then\\n            existingPath = path:match(\\"^(.*%.)PortMappingDescription$\\")\\n            break\\n        end\\n    end\\n\\n    if existingPath then\\n        log(\\"Port-forwarding rule already present\\", existingPath)\\n    else\\n        local addOk, obj = safe(addObject, portMappingBase)\\n        if addOk then\\n            log(\\"addObject(PortMapping) created instance\\", tostring(obj.instance))\\n\\n            local values = {}\\n            for name, value in pairs(desired) do\\n                values[obj.path .. name] = value\\n            end\\n\\n            if safe(setParameterValues, values) then\\n                log(\\"Port-forwarding rule configured\\", obj.path)\\n            else\\n                log(\\"Rolling back PortMapping instance after failed configuration\\", obj.path)\\n                safe(deleteObject, obj.path)\\n            end\\n        end\\n    end\\nend\\n\\nsaveDevice()\\n"]');
